#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998244353LL;
    long long value;

    Mod998() : value(0) {}
    Mod998(long long v) : value((v % MOD + MOD) % MOD) {}

    static long long modinv(long long a, long long m = MOD) {
        long long m0 = m, t, q;
        long long x0 = 0, x1 = 1;
        if (m == 1) return 0;
        while (a > 1) {
            q = a / m;
            t = m;
            m = a % m; a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }
        if (x1 < 0) x1 += m0;
        return x1;
    }

    static long long add(long long a, long long b) {
        return (a + b) % MOD;
    }

    static long long subtract(long long a, long long b) {
        return (a - b + MOD) % MOD;
    }

    static long long mult(long long a, long long b) {
        return (a * b) % MOD;
    }
};

struct InputReader {
    std::istream& in;
    std::string buffer;
    std::istringstream tokenizer;

    InputReader(std::istream& input) : in(input) {}

    std::string next() {
        while (!tokenizer || !(tokenizer >> buffer)) {
            if (!std::getline(in, buffer)) throw std::runtime_error("End of input");
            tokenizer.clear();
            tokenizer.str(buffer);
        }
        return buffer;
    }

    int nextInt() {
        return std::stoi(next());
    }
};

struct NumberTheory {
    struct Modulus {
        virtual long long modulus() const = 0;
        virtual ~Modulus() = default;
    };

    struct Mod998 : public Modulus {
        long long modulus() const override {
            return 998244353LL;
        }
    };
};

struct HZSShufflesCards {
    Mod998 mod;
    int n, m;

    void solve(int testNumber, InputReader& in, std::ostream& out) {
        n = in.nextInt();
        m = in.nextInt();

        // Precompute inverse of (n + m)
        long long inv_n_plus_m = Mod998::modinv(n + m, mod.modulus());

        long long phaseSize = 1;
        long long p = 1;
        for (int i = 0; p != 0; i++) {
            long long numerator = p;
            long long denominator = n + m - i;
            long long inv_denominator = Mod998::modinv(denominator, mod.modulus());
            p = Mod998::mult(p, n - i, inv_denominator);
            phaseSize = Mod998::add(phaseSize, p);
        }

        long long answer = 0;
        for (int k = 1; k <= n; k++) {
            long long numPhases = Mod998::mult(m + k, Mod998::modinv(k, mod.modulus()));
            long long e = Mod998::mult(numPhases, phaseSize);
            long long comb = nCr(n, k, mod.modulus());
            long long term = Mod998::mult(comb, e);
            if (k % 2 == 1) {
                answer = Mod998::add(answer, term);
            } else {
                answer = Mod998::subtract(answer, term);
            }
        }

        out << answer << "\n";
    }

    // Function to compute nCr modulo mod
    long long nCr(int n, int r, long long mod) {
        static std::vector<long long> fact, inv_fact;
        static int maxN = -1;
        if (maxN < n) {
            fact.resize(n + 1);
            inv_fact.resize(n + 1);
            fact[0] = 1;
            for (int i = 1; i <= n; i++) {
                fact[i] = (fact[i - 1] * i) % mod;
            }
            inv_fact[n] = Mod998::modinv(fact[n], mod);
            for (int i = n - 1; i >= 0; i--) {
                inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % mod;
            }
            maxN = n;
        }
        if (r < 0 || r > n) return 0;
        return (fact[n] * inv_fact[r] % mod) * inv_fact[n - r] % mod;
    }
};

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    InputReader in(std::cin);
    HZSShufflesCards solver;
    solver.solve(1, in, std::cout);
    return 0;
}

